error(message) {
  this.print_usage(writeStderr);
  this.exit(2, `${this.prog}: error: ${message}\n`);
}

/**
 * `_parse_optional`: decide whether a token is an option, a plain value, or
 * an option this parser does not know.  `sep` records whether an explicit
 * argument was introduced by `=`, which changes how a flag reacts to it.
 */
#classify(token) {
  if (token === '') return { kind: 'value' };
  if (!PREFIX_CHARS.includes(token[0])) return { kind: 'value' };
  if (this.optionStringActions.has(token)) {
    return {
      kind: 'option',
      action: this.optionStringActions.get(token),
      optionString: token,
      sep: null,
      explicitArg: null,
    };
  }
  if (Array.from(token).length === 1) return { kind: 'value' };
  if (token.includes('=')) {
    const separator = token.indexOf('=');
    const optionString = token.slice(0, separator);
    if (this.optionStringActions.has(optionString)) {
      return {
        kind: 'option',
        action: this.optionStringActions.get(optionString),
        optionString,
        sep: '=',
        explicitArg: token.slice(separator + 1),
      };
    }
  }
  const matches = this.#optionTuples(token);
  if (matches.length > 1) {
    const options = matches.map((match) => match.optionString).join(', ');
    this.error(`ambiguous option: ${token} could match ${options}`);
  }
  if (matches.length === 1) return { kind: 'option', ...matches[0] };
  if (NEGATIVE_NUMBER.test(token)) return { kind: 'value' };
  if (token.includes(' ')) return { kind: 'value' };
  return { kind: 'unknown' };
}

/** `_get_option_tuples`: abbreviations, plus `-oVALUE` style short options. */
#optionTuples(token) {
  const result = [];
  const separator = token.indexOf('=');
  if (token.startsWith('--')) {
    const optionPrefix = separator >= 0 ? token.slice(0, separator) : token;
    const sep = separator >= 0 ? '=' : null;
    const explicitArg = separator >= 0 ? token.slice(separator + 1) : null;
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString.startsWith(optionPrefix)) {
        result.push({ action, optionString, sep, explicitArg });
      }
    }
    return result;
  }
  // Single dash: either an abbreviation or a value glued to a short option.
  const shortOptionPrefix = token.slice(0, 2);
  const shortExplicitArg = token.slice(2);
  for (const [optionString, action] of this.optionStringActions) {
    if (optionString === shortOptionPrefix) {
      result.push({ action, optionString, sep: '', explicitArg: shortExplicitArg });
    } else if (optionString.startsWith(token)) {
      result.push({ action, optionString, sep: null, explicitArg: null });
    }
  }
  return result;
}

