/**
 * `consume_optional`: claim one option token plus, for a flag written as
 * `-fTAIL`, whatever further short options are glued onto it.
 *
 * @returns {number} the index to resume parsing from
 */
#consumeOptional(argv, startIndex, classified, namespace, seen, extras) {
  let { action, optionString, sep, explicitArg } = classified;
  const pending = [];
  let stopIndex;

  for (;;) {
    if (explicitArg !== null && explicitArg !== undefined) {
      const argCount = action.takesValue ? 1 : 0;
      if (argCount === 0 && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
        // A single dash flag with a tail: `-hx` runs the flag and re-reads
        // the tail as more options, but `-h=x` is always an error.
        if (sep || PREFIX_CHARS.includes(explicitArg[0])) {
          throw new ArgumentError(action, `ignored explicit argument ${reprString(explicitArg)}`);
        }
        pending.push({ action, value: null });
        const prefixChar = optionString[0];
        optionString = prefixChar + explicitArg[0];
        if (this.optionStringActions.has(optionString)) {
          action = this.optionStringActions.get(optionString);
          explicitArg = explicitArg.slice(1);
          if (explicitArg === '') explicitArg = null;
          sep = null;
        } else {
          extras.push(prefixChar + explicitArg);
          stopIndex = startIndex + 1;
          break;
        }
      } else if (argCount === 1) {
        pending.push({ action, value: explicitArg });
        stopIndex = startIndex + 1;
        break;
      } else {
        throw new ArgumentError(action, `ignored explicit argument ${reprString(explicitArg)}`);
      }
    } else if (!action.takesValue) {
      pending.push({ action, value: null });
      stopIndex = startIndex + 1;
      break;
    } else {
      // `_match_argument` for nargs=None: the very next token must be a value.
      const next = startIndex + 1 < argv.length ? argv[startIndex + 1] : null;
      const nextIsValue =
        next !== null && next !== '--' && this.#classify(next).kind === 'value';
      if (!nextIsValue) throw new ArgumentError(action, 'expected one argument');
      pending.push({ action, value: next });
      stopIndex = startIndex + 2;
      break;
    }
  }

  for (const entry of pending) this.#takeAction(entry.action, namespace, entry.value, seen);
  return stopIndex;
}
